      "id": "selenium-java-prep-85",
      "sectionId": "selenium-java",
      "sectionTitle": "Selenium WebDriver & Grid",
      "category": "Automation Framework Architecture & CI/CD",
      "question": "Explain CI/CD integration with test automation frameworks.",
      "answers": [
        "CI/CD integrates automated tests into continuous integration and deployment pipelines.",
        "CI/CD Pipeline with Tests:",
        "Developer Push Code",
        "\u2193",
        "Webhook Trigger",
        "\u2193",
        "Build Project",
        "\u2193",
        "Run Unit Tests",
        "\u2193",
        "Run Integration Tests",
        "\u2193",
        "Run Automation Tests (Smoke)",
        "\u2193",
        "Code Analysis",
        "\u2193",
        "Deploy to Staging",
        "\u2193",
        "Run Automation Tests (Full)",
        "\u2193",
        "Performance Tests",
        "\u2193",
        "Deploy to Production",
        "\u2193",
        "Monitor & Alert",
        "Jenkins Pipeline Example:",
        "pipeline {",
        "agent any",
        "stages {",
        "stage('Build') {",
        "steps {",
        "echo 'Building project...'",
        "sh 'mvn clean compile'",
        "}",
        "}",
        "stage('Unit Tests') {",
        "steps {",
        "echo 'Running unit tests...'",
        "sh 'mvn test'",
        "}",
        "}",
        "stage('Smoke Tests') {",
        "steps {",
        "echo 'Running smoke tests...'",
        "sh 'mvn test -Dgroups=smoke'",
        "}",
        "}",
        "stage('Regression Tests') {",
        "steps {",
        "echo 'Running regression tests...'",
        "sh 'mvn test -Dgroups=regression'",
        "}",
        "}",
        "stage('Deploy to Staging') {",
        "steps {",
        "echo 'Deploying to staging...'",
        "sh 'docker build -t app:${BUILD_NUMBER} .'",
        "sh 'docker push app:${BUILD_NUMBER}'",
        "sh 'kubectl set image deployment/app app=app:${BUILD_NUMBER}'",
        "}",
        "}",
        "stage('E2E Tests') {",
        "steps {",
        "echo 'Running E2E tests...'",
        "}",
        "}",
        "}",
        "post {",
        "always {",
        "// Generate reports",
        "junit 'target/surefire-reports/*.xml'",
        "publishHTML([",
        "reportDir: 'target/surefire-reports',",
        "reportFiles: 'index.html',",
        "reportName: 'Test Report'",
        "])",
        "// Archive test results",
        "archiveArtifacts artifacts: 'target/**', allowEmptyArchive: true",
        "}",
        "success {",
        "echo 'Pipeline succeeded!'",
        "// Deploy to production",
        "}",
        "failure {",
        "echo 'Pipeline failed!'",
        "// Send notification",
        "emailext(",
        "to: '${DEFAULT_RECIPIENTS}',",
        "subject: 'Build Failed: ${BUILD_NUMBER}',",
        "body: 'Test execution failed. Check logs for details.'",
        ")",
        "}",
        "}",
        "}",
        "POM Configuration:",
        "<plugin>",
        "<groupId>org.apache.maven.plugins</groupId>",
        "<artifactId>maven-surefire-plugin</artifactId>",
        "<version>3.0.0-M5</version>",
        "<configuration>",
        "<includes>",
        "<include>**/*Test.java</include>",
        "</includes>",
        "<suiteXmlFiles>",
        "<suiteXmlFile>${testngFile}</suiteXmlFile>",
        "</suiteXmlFiles>",
        "<parallel>methods</parallel>",
        "<threadCount>4</threadCount>",
        "</configuration>",
        "</plugin>",
        "<plugin>",
        "<groupId>org.jacoco</groupId>",
        "<artifactId>jacoco-maven-plugin</artifactId>",
        "<version>0.8.7</version>",
        "<executions>",
        "<execution>",
        "<goals>",
        "<goal>prepare-agent</goal>",
        "</goals>",
        "</execution>",
        "</executions>",
        "</plugin>"
      ],
      "difficulty": "Intermediate"
